import * as THREE from './vendor/three.module.js';
export function createFinale(scene,reduced){let fire=null,started=0,texture=null;
function flameTexture(){if(texture)return texture;const c=document.createElement('canvas');c.width=128;c.height=192;const ctx=c.getContext('2d'),g=ctx.createRadialGradient(63,139,2,64,111,93);g.addColorStop(0,'rgba(255,255,220,1)');g.addColorStop(.24,'rgba(255,230,90,1)');g.addColorStop(.55,'rgba(255,128,12,.9)');g.addColorStop(.78,'rgba(245,43,0,.48)');g.addColorStop(1,'rgba(150,10,0,0)');ctx.fillStyle=g;ctx.shadowColor='#ff6b0a';ctx.shadowBlur=15;ctx.beginPath();ctx.moveTo(64,185);ctx.bezierCurveTo(2,160,6,102,40,73);ctx.bezierCurveTo(34,117,58,102,58,13);ctx.bezierCurveTo(111,54,78,93,97,112);ctx.bezierCurveTo(115,96,130,151,64,185);ctx.fill();texture=new THREE.CanvasTexture(c);texture.colorSpace=THREE.SRGBColorSpace;return texture}
function clear(){if(fire){scene.remove(fire);fire.children.forEach(s=>s.material.dispose());fire=null}started=0;}
function start(center,color,count){clear();started=performance.now();fire=new THREE.Group();fire.position.copy(center);const map=flameTexture(),n=reduced?18:65;for(let i=0;i<n;i++){const mat=new THREE.SpriteMaterial({map,color:i%4===0?'#fff5c5':i%3===0?'#ff7b24':'#ffc562',transparent:true,opacity:.8,blending:THREE.AdditiveBlending,depthWrite:false});const sprite=new THREE.Sprite(mat),a=Math.random()*Math.PI*2,z=Math.random()*2-1,s=Math.sqrt(1-z*z),speed=i<8?.5:1.8+Math.random()*3.7;sprite.userData={v:new THREE.Vector3(Math.cos(a)*s,z*.8+.45,Math.sin(a)*s).multiplyScalar(speed),size:i<8?1.5+Math.random():.3+Math.random()*.75,birth:i<8?0:Math.random()*.16,life:.6+Math.random()*.65,phase:Math.random()*6.28};fire.add(sprite)}scene.add(fire);}
function update(){if(!started)return false;const t=(performance.now()-started)/1000;if(t>1.35){clear();return false}for(const s of fire.children){const d=s.userData,age=t-d.birth,k=Math.max(0,Math.min(1,age/d.life));s.visible=age>=0&&k<1;if(!s.visible)continue;const motion=reduced?.35:1;s.position.copy(d.v).multiplyScalar(age*motion);s.position.y+=age*age*1.9;const envelope=Math.pow(Math.sin(k*Math.PI),.55),flicker=1+Math.sin(age*34+d.phase)*.10;s.scale.set(d.size*envelope*flicker,d.size*envelope*(1.45+age*.4),1);s.material.rotation=Math.sin(age*9+d.phase)*.12;s.material.opacity=(1-k)*.78;}return true}
return{start,update,clear,get active(){return !!started}};
}
